// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        amount = bound(amount, 1, 10 ether);
        vm.deal(actor, amount);

        (, uint256 balBefore) = c.Acc(actor);
        vm.prank(actor);
        c.Put{value: amount}(0);
        (, uint256 balAfter) = c.Acc(actor);

        assertTrue(balAfter == balBefore + amount);
    }
}
